import React, { useEffect, useState } from 'react';
import api from '../../api/axios';

export default function PageDashboard() {
  const [machines, setMachines]   = useState([]);
  const [alertes, setAlertes]     = useState([]);
  const [loading, setLoading]     = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/machines'),
      api.get('/alertes'),
    ]).then(([m, a]) => {
      setMachines(m.data);
      setAlertes(a.data);
      setLoading(false);
    });
  }, []);

  if (loading) return <div style={S.loading}>Chargement...</div>;

  const totalMachines  = machines.length;
  const enService      = machines.filter(m => m.statut === 'EN SERVICE').length;
  const alertesCrit    = alertes.filter(a => a.niveau === 'CRITIQUE' && !a.acquittee).length;
  const alertesWarn    = alertes.filter(a => a.niveau === 'WARNING'  && !a.acquittee).length;
  const alertesTotal   = alertes.filter(a => !a.acquittee).length;

  return (
    <div>
      {/* Métriques */}
      <div style={S.metricsRow}>
        <MetricCard
          label="MACHINES ACTIVES"
          value={enService}
          unit={`/ ${totalMachines}`}
          color="#2ed573"
          status="En ligne"
          statusOk
        />
        <MetricCard
          label="ALERTES CRITIQUES"
          value={alertesCrit}
          color="#ff4757"
          status={alertesCrit > 0 ? 'Action requise' : 'Aucune alerte'}
          statusOk={alertesCrit === 0}
        />
        <MetricCard
          label="ALERTES WARNING"
          value={alertesWarn}
          color="#f5a623"
          status={alertesWarn > 0 ? 'À surveiller' : 'Aucune alerte'}
          statusOk={alertesWarn === 0}
        />
        <MetricCard
          label="TOTAL ALERTES"
          value={alertesTotal}
          color="#0099ff"
          status="Non acquittées"
          statusOk={alertesTotal === 0}
        />
      </div>

      {/* Machines + Alertes récentes */}
      <div style={S.grid2}>
        {/* Machines */}
        <div style={S.card}>
          <div style={S.cardHead}>
            <span style={S.cardTitle}>ÉTAT DES MACHINES</span>
          </div>
          <table style={S.tbl}>
            <thead>
              <tr>
                <th style={S.th}>Machine</th>
                <th style={S.th}>Localisation</th>
                <th style={S.th}>Statut</th>
              </tr>
            </thead>
            <tbody>
              {machines.map(m => (
                <tr key={m.id}>
                  <td style={S.td}>{m.nom}</td>
                  <td style={{...S.td, color:'#7a8394', fontFamily:'monospace', fontSize:11}}>{m.localisation}</td>
                  <td style={S.td}>
                    <span style={{...S.badge, ...(m.statut==='EN SERVICE' ? S.badgeOk : S.badgeErr)}}>
                      {m.statut}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Alertes récentes */}
        <div style={S.card}>
          <div style={S.cardHead}>
            <span style={S.cardTitle}>ALERTES RÉCENTES</span>
          </div>
          {alertes.slice(0, 5).map(a => (
            <div key={a.id} style={{...S.alertItem, opacity: a.acquittee ? 0.4 : 1}}>
              <div style={{...S.alertDot, background: a.niveau==='CRITIQUE' ? '#ff4757' : a.niveau==='WARNING' ? '#f5a623' : '#2ed573'}}/>
              <div style={{flex:1}}>
                <div style={S.alertMsg}>{a.message}</div>
                <div style={S.alertMeta}>
                  <span style={{...S.pill, ...(a.niveau==='CRITIQUE' ? S.pillErr : S.pillWarn)}}>
                    {a.niveau}
                  </span>
                  <span style={S.alertTime}>
                    {new Date(a.cree_le).toLocaleDateString('fr-FR')}
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function MetricCard({ label, value, unit, color, status, statusOk }) {
  return (
    <div style={S.mcard}>
      <div style={{...S.mcardBar, background: color}}/>
      <div style={S.mcardLabel}>{label}</div>
      <div style={S.mcardVal}>
        {value}
        {unit && <span style={S.mcardUnit}>{unit}</span>}
      </div>
      <div style={S.mcardStatus}>
        <span style={{...S.dot, background: statusOk ? '#2ed573' : color}}/>
        <span style={{color: statusOk ? '#2ed573' : color, fontSize:11}}>{status}</span>
      </div>
    </div>
  );
}

const S = {
  loading:    { color:'#7a8394', textAlign:'center', marginTop:40 },
  metricsRow: { display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:14, marginBottom:20 },
  mcard:      { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'18px 20px', position:'relative', overflow:'hidden' },
  mcardBar:   { position:'absolute', top:0, left:0, right:0, height:2 },
  mcardLabel: { fontFamily:'monospace', fontSize:10, color:'#4a5260', letterSpacing:1.5, textTransform:'uppercase', marginBottom:12 },
  mcardVal:   { fontSize:28, fontWeight:600, color:'#e8eaf0', fontFamily:'monospace' },
  mcardUnit:  { fontSize:13, color:'#7a8394', marginLeft:4 },
  mcardStatus:{ display:'flex', alignItems:'center', gap:5, marginTop:8 },
  dot:        { width:5, height:5, borderRadius:'50%', flexShrink:0 },
  grid2:      { display:'grid', gridTemplateColumns:'2fr 1fr', gap:16 },
  card:       { background:'#161b22', border:'1px solid rgba(255,255,255,0.07)', borderRadius:10, padding:'20px 22px' },
  cardHead:   { marginBottom:18 },
  cardTitle:  { fontFamily:'monospace', fontSize:11, color:'#7a8394', letterSpacing:1, textTransform:'uppercase' },
  tbl:        { width:'100%', borderCollapse:'collapse' },
  th:         { textAlign:'left', fontFamily:'monospace', fontSize:10, color:'#4a5260', letterSpacing:1, textTransform:'uppercase', paddingBottom:12, borderBottom:'1px solid rgba(255,255,255,0.07)' },
  td:         { padding:'11px 0', borderBottom:'1px solid rgba(255,255,255,0.05)', color:'#e8eaf0', fontSize:13 },
  badge:      { display:'inline-flex', fontFamily:'monospace', fontSize:10, padding:'3px 8px', borderRadius:4 },
  badgeOk:    { background:'rgba(46,213,115,0.15)',  color:'#2ed573' },
  badgeErr:   { background:'rgba(255,71,87,0.15)',   color:'#ff4757' },
  alertItem:  { display:'flex', gap:12, alignItems:'flex-start', padding:'12px 0', borderBottom:'1px solid rgba(255,255,255,0.05)' },
  alertDot:   { width:7, height:7, borderRadius:'50%', marginTop:4, flexShrink:0 },
  alertMsg:   { fontSize:12, color:'#e8eaf0', marginBottom:6 },
  alertMeta:  { display:'flex', alignItems:'center', gap:8 },
  alertTime:  { fontSize:11, color:'#4a5260', fontFamily:'monospace' },
  pill:       { fontFamily:'monospace', fontSize:10, padding:'2px 6px', borderRadius:4 },
  pillErr:    { background:'rgba(255,71,87,0.15)',   color:'#ff4757' },
  pillWarn:   { background:'rgba(245,166,35,0.15)',  color:'#f5a623' },
};
